// Obtener los estados y el estado actual
let estados = global.get("estados") || {};
let estado_actual = global.get("estado_actual") || "CHAMBER_OPEN";

// Obtener todas las claves donde ILOCK está en 1
let estados_ilock = Object.keys(estados).filter(key => estados[key].ILOCK === 1);

if (estados_ilock.length === 0) {
    // Error: No hay ningún estado con ILOCK en 1
    let msg3 = { payload: "Error: Ningún estado tiene ILOCK en 1" };
    return [null, null, msg3];

} else if (estados_ilock.length > 1) {
    // Error: Hay más de un estado con ILOCK en 1
    let msg3 = { payload: "Error: Más de un estado tiene ILOCK en 1" };
    return [null, null, msg3];
}

// Solo hay un estado válido
