// Verificar si todas las condiciones para cambiar de estado están en 1
if (estado_info.ILOCK === 1 && estado_info.EXT_SYNC === 1 && estado_info.TRANS === 1) {

    // Obtener la lista de estados en orden
    let orden_estados = Object.keys(estados);

    // Obtener el índice del estado actual
    let indice_actual = orden_estados.indexOf(estado_key);

    // Calcular el siguiente estado en bucle
    let nuevo_estado_key = orden_estados[(indice_actual + 1) % orden_estados.length];
    let nuevo_estado = estados[nuevo_estado_key].STATE;

    // Poner todos los ILOCK, EXT_SYNC y TRANS a 0
    Object.keys(estados).forEach(key => {
        estados[key].ILOCK = 0;
        estados[key].EXT_SYNC = 0;
        estados[key].TRANS = 0;
    });

    // Activar solo el ILOCK del nuevo estado
    estados[nuevo_estado_key].ILOCK = 1;

    // Actualizar en la variable global
    global.set("estados", estados);
    global.set("estado_actual", nuevo_estado);

    // Salida con el nuevo estado
    let msg2 = { payload: "Nuevo estado: " + nuevo_estado };
    return [null, msg2, null];
}

